<?php
/**
 * Site editor in wp-admin experiment.
 *
 * Shows the extensible site editor inside wp-admin, using the
 * `site-editor-v2-wp-admin` page generated by `@wordpress/build`, and lists its
 * sections under Appearance in the admin menu. Only loaded while both the
 * `gutenberg-extensible-site-editor` and `gutenberg-site-editor-wp-admin`
 * experiments are enabled (see lib/load.php).
 *
 * @package gutenberg
 */

// This experiment replaces the Appearance menu item pointing at the
// fullscreen extensible site editor.
remove_action( 'admin_menu', 'gutenberg_redirect_to_extensible_site_editor', 100 );

/**
 * Returns the URL of the site editor page inside wp-admin, relative to the
 * admin URL.
 *
 * @param string $path Optional. Route path to open.
 * @return string The page URL.
 */
function gutenberg_get_site_editor_wp_admin_url( $path = '/' ) {
	$url = 'themes.php?page=site-editor-v2-wp-admin';
	if ( '/' !== $path ) {
		$url .= '&p=' . $path;
	}
	return $url;
}

/**
 * Returns the site editor sections listed in the admin menu.
 *
 * Pages is left out because the top-level Pages menu already covers it.
 *
 * @return array[] List of sections, each with `id`, `label` and `to` keys.
 */
function gutenberg_get_site_editor_wp_admin_sections() {
	return array_values(
		array_filter(
			gutenberg_get_site_editor_sections(),
			static function ( $section ) {
				return 'pages' !== $section['id'];
			}
		)
	);
}

/**
 * Registers the site editor page under Appearance, and replaces Core's site
 * editor submenu items with one item per site editor section.
 *
 * @global array $submenu WordPress admin submenu array.
 */
function gutenberg_register_site_editor_wp_admin_menu() {
	global $submenu;

	if ( empty( $submenu['themes.php'] ) ) {
		return;
	}

	// Core only adds site editor items (Editor, Patterns, Template Parts) when
	// the theme supports them, so use their presence as the gate.
	$insert_at = null;
	foreach ( $submenu['themes.php'] as $key => $item ) {
		if ( isset( $item[2] ) && str_starts_with( $item[2], 'site-editor.php' ) ) {
			if ( null === $insert_at ) {
				$insert_at = $key;
			}
			unset( $submenu['themes.php'][ $key ] );
		}
	}

	if ( null === $insert_at ) {
		return;
	}

	$hook_suffix = add_submenu_page(
		'themes.php',
		__( 'Site Editor', 'gutenberg' ),
		__( 'Editor', 'gutenberg' ),
		'edit_theme_options',
		'site-editor-v2-wp-admin',
		'gutenberg_site_editor_v2_wp_admin_render_page'
	);

	if ( $hook_suffix ) {
		add_action( "load-$hook_suffix", 'gutenberg_site_editor_wp_admin_prepare_screen' );
	}

	// `add_submenu_page()` appends the item; move it to where Core's Editor
	// item was, followed by the other sections.
	$editor_item = array_pop( $submenu['themes.php'] );
	$new_items   = array( $editor_item );
	foreach ( gutenberg_get_site_editor_wp_admin_sections() as $section ) {
		if ( '/' === $section['to'] ) {
			continue;
		}
		$new_items[] = array(
			$section['label'],
			'edit_theme_options',
			gutenberg_get_site_editor_wp_admin_url( $section['to'] ),
			$section['label'],
		);
	}

	$reordered = array();
	foreach ( $submenu['themes.php'] as $key => $item ) {
		if ( $key > $insert_at && ! empty( $new_items ) ) {
			array_push( $reordered, ...$new_items );
			$new_items = array();
		}
		$reordered[] = $item;
	}
	array_push( $reordered, ...$new_items );

	$submenu['themes.php'] = $reordered; // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited
}
add_action( 'admin_menu', 'gutenberg_register_site_editor_wp_admin_menu', 100 );

/**
 * Returns the menu slug of the section matching a route path, using the
 * longest section path that the route path starts with.
 *
 * @param string $path Route path, as in the `p` query arg.
 * @return string The menu slug.
 */
function gutenberg_get_site_editor_wp_admin_submenu_file( $path ) {
	$path     = '/' . trim( explode( '?', $path )[0], '/' );
	$best     = '/';
	$best_len = 0;

	foreach ( gutenberg_get_site_editor_wp_admin_sections() as $section ) {
		$to = $section['to'];
		if ( '/' === $to ) {
			continue;
		}
		$matches = $path === $to || str_starts_with( $path, $to . '/' );
		if ( $matches && strlen( $to ) > $best_len ) {
			$best     = $to;
			$best_len = strlen( $to );
		}
	}

	if ( '/' === $best ) {
		return 'site-editor-v2-wp-admin';
	}
	return gutenberg_get_site_editor_wp_admin_url( $best );
}

/**
 * Prepares the admin menu highlight and the data the page needs before
 * wp-admin/admin-header.php renders.
 */
function gutenberg_site_editor_wp_admin_prepare_screen() {
	// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Only picks the highlighted menu item.
	$path = isset( $_GET['p'] ) && is_string( $_GET['p'] ) ? sanitize_text_field( wp_unslash( $_GET['p'] ) ) : '/';

	add_filter(
		'submenu_file',
		static function () use ( $path ) {
			return gutenberg_get_site_editor_wp_admin_submenu_file( $path );
		}
	);
}

add_action( 'site-editor-v2-wp-admin_init', '_gutenberg_preload_route_entity_fields' );
